*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg: #fff;
  --color-bg-alt: #f5f5f7;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-link: #0066cc;
  --color-link-hover: #004499;
  --color-border: #d2d2d7;
  --color-card-bg: #fbfbfd;
  --font-stack: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  --max-width: 1440px;
  --section-padding: 80px 0;
  --card-radius: 18px;
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; font-size: 16px; }
body { font-family: var(--font-stack); color: var(--color-text); background: var(--color-bg); line-height: 1.5; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
a { color: var(--color-link); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--color-link-hover); }
img { max-width: 100%; height: auto; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== RIBBON BANNER ===== */
.ribbon { background: var(--color-bg-alt); text-align: center; padding: 12px 24px; font-size: 14px; color: var(--color-text-secondary); }
.ribbon a { font-size: 14px; }

/* ===== TOP NAV ===== */
.top-nav { background: rgba(255,255,255,0.92); backdrop-filter: saturate(180%) blur(20px); -webkit-backdrop-filter: saturate(180%) blur(20px); position: sticky; top: 0; z-index: 1000; border-bottom: 1px solid var(--color-border); }
.top-nav .container { display: flex; align-items: center; justify-content: space-between; height: 48px; }
.nav-logo { font-size: 20px; font-weight: 700; color: var(--color-text); letter-spacing: -0.5px; }
.nav-links { display: flex; gap: 32px; align-items: center; }
.nav-links a { font-size: 13px; color: var(--color-text-secondary); font-weight: 400; transition: color var(--transition); }
.nav-links a:hover { color: var(--color-text); }
.nav-links a.active { color: var(--color-text); font-weight: 600; }
.nav-hamburger { display: none; width: 44px; height: 44px; align-items: center; justify-content: center; flex-direction: column; gap: 5px; }
.nav-hamburger span { display: block; width: 18px; height: 1.5px; background: var(--color-text); transition: var(--transition); }

/* ===== SECTION HEADERS ===== */
.section-header { padding: 0 0 40px; }
.section-header h2 { font-size: 48px; font-weight: 700; letter-spacing: -0.03em; line-height: 1.1; color: var(--color-text); }
.section-header p { font-size: 20px; color: var(--color-text-secondary); margin-top: 8px; font-weight: 400; }

/* ===== CAROUSEL ===== */
.carousel-section { padding: var(--section-padding); overflow: hidden; }
.carousel-wrapper { position: relative; }
.carousel-track { display: flex; gap: 20px; overflow-x: auto; scroll-behavior: smooth; scrollbar-width: none; -ms-overflow-style: none; padding: 4px 0; scroll-snap-type: x mandatory; }
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-track > * { scroll-snap-align: start; flex-shrink: 0; }

.carousel-nav { display: flex; gap: 12px; margin-top: 24px; justify-content: flex-end; padding-right: 4px; }
.carousel-btn { width: 40px; height: 40px; border-radius: 50%; background: var(--color-bg-alt); border: 1px solid var(--color-border); display: flex; align-items: center; justify-content: center; transition: all var(--transition); color: var(--color-text); }
.carousel-btn:hover { background: var(--color-border); }
.carousel-btn:disabled { opacity: 0.3; cursor: default; }
.carousel-btn svg { width: 16px; height: 16px; }

/* ===== PRODUCT CARDS (Latest) ===== */
.product-card { width: 340px; background: var(--color-bg-alt); border-radius: var(--card-radius); overflow: hidden; transition: transform var(--transition), box-shadow var(--transition); }
.product-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.08); }
.product-card-image { height: 260px; display: flex; align-items: center; justify-content: center; position: relative; }
.product-card-image .placeholder-icon { font-size: 64px; color: var(--color-text-secondary); opacity: 0.3; }
.product-card-badge { position: absolute; top: 16px; left: 16px; background: #e8432d; color: #fff; font-size: 11px; font-weight: 600; padding: 4px 10px; border-radius: 12px; letter-spacing: 0.02em; text-transform: uppercase; }
.product-card-info { padding: 24px; }
.product-card-info h3 { font-size: 20px; font-weight: 600; margin-bottom: 4px; }
.product-card-info .tagline { font-size: 14px; color: var(--color-text-secondary); margin-bottom: 16px; line-height: 1.4; }
.product-card-info .price { font-size: 15px; font-weight: 500; }
.product-card-info .monthly { font-size: 13px; color: var(--color-text-secondary); margin-top: 2px; }

/* Color variants for product cards */
.product-card.bg-dark { background: #1d1d1f; color: #f5f5f7; }
.product-card.bg-dark .tagline, .product-card.bg-dark .monthly { color: #a1a1a6; }
.product-card.bg-dark .price { color: #f5f5f7; }
.product-card.bg-blue { background: linear-gradient(135deg, #1a3a5c 0%, #0d2137 100%); color: #f5f5f7; }
.product-card.bg-blue .tagline, .product-card.bg-blue .monthly { color: #a1a1a6; }
.product-card.bg-blue .price { color: #f5f5f7; }
.product-card.bg-warm { background: linear-gradient(135deg, #faf5f0 0%, #f5ede3 100%); }
.product-card.bg-cool { background: linear-gradient(135deg, #eef2f7 0%, #e3eaf5 100%); }
.product-card.bg-green { background: linear-gradient(135deg, #edf5f0 0%, #d8ede0 100%); }
.product-card.bg-purple { background: linear-gradient(135deg, #f0eef5 0%, #e3daf0 100%); }

/* ===== SMALL CARDS (Accessories, Audio, Help, etc.) ===== */
.small-card { width: 280px; background: var(--color-bg-alt); border-radius: var(--card-radius); overflow: hidden; transition: transform var(--transition), box-shadow var(--transition); }
.small-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.08); }
.small-card-image { height: 200px; display: flex; align-items: center; justify-content: center; background: #fff; }
.small-card-image .placeholder-icon { font-size: 48px; color: var(--color-text-secondary); opacity: 0.3; }
.small-card-info { padding: 20px; }
.small-card-info h4 { font-size: 16px; font-weight: 600; margin-bottom: 4px; line-height: 1.3; }
.small-card-info .card-desc { font-size: 13px; color: var(--color-text-secondary); margin-bottom: 8px; line-height: 1.4; }
.small-card-info .card-price { font-size: 15px; font-weight: 600; }
.small-card-info .card-note { font-size: 12px; color: var(--color-link); margin-top: 4px; }

/* ===== HERO PRODUCT GRID (Homepage) ===== */
.hero-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; padding: 60px 0; }
.hero-tile { border-radius: var(--card-radius); overflow: hidden; min-height: 500px; display: flex; flex-direction: column; align-items: center; padding: 48px 32px; text-align: center; position: relative; transition: transform var(--transition); }
.hero-tile:hover { transform: scale(1.01); }
.hero-tile.dark { background: #1d1d1f; color: #f5f5f7; }
.hero-tile.light { background: var(--color-bg-alt); color: var(--color-text); }
.hero-tile.gradient-blue { background: linear-gradient(180deg, #1b3a5c 0%, #0a1f35 100%); color: #f5f5f7; }
.hero-tile.gradient-warm { background: linear-gradient(180deg, #faf5f0 0%, #f0e6d8 100%); color: var(--color-text); }
.hero-tile.gradient-green { background: linear-gradient(180deg, #e8f5e9 0%, #c8e6c9 100%); color: var(--color-text); }
.hero-tile.gradient-purple { background: linear-gradient(180deg, #f3e5f5 0%, #e1bee7 100%); color: var(--color-text); }
.hero-tile h2 { font-size: 40px; font-weight: 700; letter-spacing: -0.03em; margin-bottom: 8px; }
.hero-tile .hero-tagline { font-size: 18px; opacity: 0.85; margin-bottom: 16px; font-weight: 400; }
.hero-tile .hero-ctas { display: flex; gap: 24px; margin-bottom: 32px; }
.hero-tile .hero-ctas a { font-size: 17px; font-weight: 400; }
.hero-tile.dark .hero-ctas a { color: #6bc1ff; }
.hero-tile.light .hero-ctas a, .hero-tile.gradient-warm .hero-ctas a, .hero-tile.gradient-green .hero-ctas a, .hero-tile.gradient-purple .hero-ctas a { color: var(--color-link); }
.hero-tile.gradient-blue .hero-ctas a { color: #6bc1ff; }
.hero-tile .hero-image-area { flex: 1; display: flex; align-items: center; justify-content: center; width: 100%; }
.hero-tile .product-silhouette { width: 280px; height: 200px; border-radius: 20px; display: flex; align-items: center; justify-content: center; }
.hero-tile.dark .product-silhouette { background: rgba(255,255,255,0.06); }
.hero-tile.light .product-silhouette, .hero-tile.gradient-warm .product-silhouette, .hero-tile.gradient-green .product-silhouette, .hero-tile.gradient-purple .product-silhouette { background: rgba(0,0,0,0.04); }
.hero-tile.gradient-blue .product-silhouette { background: rgba(255,255,255,0.06); }
.product-silhouette svg { width: 80px; height: 80px; opacity: 0.25; }

/* ===== ENTERTAINMENT TABS ===== */
.entertainment-section { padding: var(--section-padding); background: var(--color-bg-alt); }
.ent-tabs { display: flex; gap: 8px; margin-bottom: 40px; flex-wrap: wrap; }
.ent-tab { padding: 10px 24px; border-radius: 100px; font-size: 15px; font-weight: 500; color: var(--color-text-secondary); background: #fff; border: 1px solid var(--color-border); transition: all var(--transition); }
.ent-tab:hover { border-color: var(--color-text-secondary); }
.ent-tab.active { background: var(--color-text); color: #fff; border-color: var(--color-text); }
.ent-panel { display: none; }
.ent-panel.active { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 20px; }
.ent-card { background: #fff; border-radius: 16px; overflow: hidden; transition: transform var(--transition), box-shadow var(--transition); }
.ent-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.08); }
.ent-card-image { height: 180px; display: flex; align-items: center; justify-content: center; }
.ent-card-image .placeholder-icon { font-size: 40px; opacity: 0.2; }
.ent-card.streaming .ent-card-image { background: linear-gradient(135deg, #1a1a2e, #16213e); }
.ent-card.fitness .ent-card-image { background: linear-gradient(135deg, #1b4332, #2d6a4f); }
.ent-card.gaming .ent-card-image { background: linear-gradient(135deg, #2d1b69, #4a1a8a); }
.ent-card.music .ent-card-image { background: linear-gradient(135deg, #7f1d1d, #991b1b); }
.ent-card-body { padding: 16px 20px; }
.ent-card-body h4 { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
.ent-card-body p { font-size: 13px; color: var(--color-text-secondary); margin-bottom: 12px; }
.ent-card-body a { font-size: 13px; font-weight: 500; }

/* ===== ICON BAR ===== */
.icon-bar { padding: 32px 0; border-bottom: 1px solid var(--color-border); overflow-x: auto; scrollbar-width: none; -ms-overflow-style: none; }
.icon-bar::-webkit-scrollbar { display: none; }
.icon-bar-inner { display: flex; gap: 40px; justify-content: center; min-width: max-content; padding: 0 24px; }
.icon-item { display: flex; flex-direction: column; align-items: center; gap: 8px; text-decoration: none; color: var(--color-text); transition: opacity var(--transition); min-width: 72px; }
.icon-item:hover { opacity: 0.7; color: var(--color-text); }
.icon-item .icon-circle { width: 56px; height: 56px; border-radius: 50%; background: var(--color-bg-alt); display: flex; align-items: center; justify-content: center; }
.icon-circle svg { width: 24px; height: 24px; color: var(--color-text-secondary); }
.icon-item span { font-size: 12px; color: var(--color-text-secondary); white-space: nowrap; }

/* ===== STORE HERO ===== */
.store-hero { text-align: center; padding: 60px 24px 40px; }
.store-hero h1 { font-size: 56px; font-weight: 700; letter-spacing: -0.04em; }
.store-hero p { font-size: 22px; color: var(--color-text-secondary); margin-top: 8px; }
.store-hero .hero-links { display: flex; gap: 24px; justify-content: center; margin-top: 16px; flex-wrap: wrap; }
.store-hero .hero-links a { font-size: 17px; }

/* ===== HELP & STORE DIFF ===== */
.info-card { width: 300px; background: #fff; border-radius: var(--card-radius); padding: 32px 24px; text-align: center; transition: transform var(--transition), box-shadow var(--transition); border: 1px solid #f0f0f0; }
.info-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.06); }
.info-card .card-icon { width: 48px; height: 48px; margin: 0 auto 16px; border-radius: 50%; background: var(--color-bg-alt); display: flex; align-items: center; justify-content: center; }
.info-card .card-icon svg { width: 22px; height: 22px; color: var(--color-link); }
.info-card h4 { font-size: 17px; font-weight: 600; margin-bottom: 6px; }
.info-card p { font-size: 14px; color: var(--color-text-secondary); line-height: 1.5; }

/* ===== BRAND COLLAB ===== */
.brand-collab { padding: var(--section-padding); text-align: center; background: linear-gradient(135deg, #1d1d1f 0%, #2d2d30 100%); color: #f5f5f7; }
.brand-collab h2 { font-size: 48px; font-weight: 700; letter-spacing: -0.03em; }
.brand-collab p { font-size: 18px; color: #a1a1a6; margin-top: 8px; max-width: 600px; margin-left: auto; margin-right: auto; }

/* ===== QUICK LINKS ===== */
.quick-links { padding: 40px 0; }
.quick-links-inner { display: flex; gap: 12px; flex-wrap: wrap; justify-content: center; }
.quick-link { padding: 10px 24px; border-radius: 100px; border: 1px solid var(--color-border); font-size: 14px; color: var(--color-text); transition: all var(--transition); background: #fff; }
.quick-link:hover { background: var(--color-bg-alt); border-color: var(--color-text-secondary); color: var(--color-text); }

/* ===== CATEGORY PAGE HERO ===== */
.category-hero { text-align: center; padding: 60px 24px 20px; }
.category-hero h1 { font-size: 56px; font-weight: 700; letter-spacing: -0.04em; }
.category-hero p { font-size: 20px; color: var(--color-text-secondary); margin-top: 8px; }

/* ===== STICKY SECTION NAV ===== */
.section-nav { position: sticky; top: 48px; z-index: 900; background: rgba(255,255,255,0.92); backdrop-filter: saturate(180%) blur(20px); -webkit-backdrop-filter: saturate(180%) blur(20px); border-bottom: 1px solid var(--color-border); overflow-x: auto; scrollbar-width: none; -ms-overflow-style: none; }
.section-nav::-webkit-scrollbar { display: none; }
.section-nav-inner { display: flex; gap: 32px; justify-content: center; padding: 0 24px; min-width: max-content; }
.section-nav a { display: block; padding: 14px 0; font-size: 14px; color: var(--color-text-secondary); white-space: nowrap; border-bottom: 2px solid transparent; transition: all var(--transition); }
.section-nav a:hover { color: var(--color-text); }
.section-nav a.active { color: var(--color-text); border-bottom-color: var(--color-text); font-weight: 600; }

/* ===== MODEL CARD ===== */
.model-card { width: 320px; background: var(--color-bg-alt); border-radius: var(--card-radius); overflow: hidden; transition: transform var(--transition), box-shadow var(--transition); }
.model-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.08); }
.model-card-image { height: 240px; display: flex; align-items: center; justify-content: center; position: relative; background: #fff; }
.model-card-image .placeholder-icon { font-size: 56px; opacity: 0.2; }
.model-card-badge { position: absolute; top: 16px; left: 16px; background: #e8432d; color: #fff; font-size: 11px; font-weight: 600; padding: 4px 10px; border-radius: 12px; text-transform: uppercase; }
.model-card-info { padding: 24px; text-align: center; }
.model-card-info h3 { font-size: 22px; font-weight: 600; margin-bottom: 12px; }
.model-card-info .price { font-size: 15px; font-weight: 500; }
.model-card-info .monthly { font-size: 13px; color: var(--color-text-secondary); margin-top: 4px; }
.model-card-info .card-ctas { display: flex; gap: 20px; justify-content: center; margin-top: 16px; }
.model-card-info .card-ctas a { font-size: 14px; }

/* ===== GUIDE/SAVE CARD ===== */
.guide-card { width: 300px; background: var(--color-bg-alt); border-radius: var(--card-radius); padding: 32px 24px; transition: transform var(--transition), box-shadow var(--transition); }
.guide-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.06); }
.guide-card h4 { font-size: 18px; font-weight: 600; margin-bottom: 8px; }
.guide-card p { font-size: 14px; color: var(--color-text-secondary); line-height: 1.5; }
.guide-card a.card-link { display: inline-block; margin-top: 12px; font-size: 14px; font-weight: 500; }

/* ===== FOOTER ===== */
.site-footer { background: var(--color-bg-alt); border-top: 1px solid var(--color-border); padding: 48px 0 24px; margin-top: 60px; }
.footer-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 32px; margin-bottom: 40px; }
.footer-col h5 { font-size: 13px; font-weight: 600; margin-bottom: 12px; color: var(--color-text); cursor: default; }
.footer-col ul li { margin-bottom: 6px; }
.footer-col ul li a { font-size: 12px; color: var(--color-text-secondary); }
.footer-col ul li a:hover { color: var(--color-text); }
.footer-legal { border-top: 1px solid var(--color-border); padding-top: 20px; font-size: 12px; color: var(--color-text-secondary); line-height: 1.6; }
.footer-legal p { margin-bottom: 8px; }
.footer-bottom { display: flex; justify-content: space-between; align-items: center; margin-top: 12px; font-size: 12px; color: var(--color-text-secondary); flex-wrap: wrap; gap: 8px; }

/* ===== PROMO BANNER (in-section) ===== */
.promo-note { font-size: 14px; color: var(--color-link); margin-top: -20px; margin-bottom: 30px; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .hero-grid { grid-template-columns: 1fr 1fr; }
  .hero-tile { min-height: 420px; padding: 36px 24px; }
  .hero-tile h2 { font-size: 32px; }
  .section-header h2 { font-size: 40px; }
  .store-hero h1, .category-hero h1 { font-size: 44px; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-hamburger { display: flex; }
  .nav-links.open { display: flex; position: absolute; top: 48px; left: 0; right: 0; background: rgba(255,255,255,0.98); backdrop-filter: blur(20px); flex-direction: column; gap: 0; padding: 12px 0; border-bottom: 1px solid var(--color-border); }
  .nav-links.open a { padding: 12px 24px; width: 100%; }

  .hero-grid { grid-template-columns: 1fr; }
  .hero-tile { min-height: 380px; }
  .hero-tile h2 { font-size: 28px; }
  .hero-tile .hero-tagline { font-size: 16px; }
  .section-header h2 { font-size: 32px; }
  .store-hero h1, .category-hero h1 { font-size: 36px; }
  .store-hero p, .category-hero p { font-size: 17px; }

  .product-card { width: 300px; }
  .small-card { width: 260px; }
  .model-card { width: 280px; }
  .guide-card { width: 280px; }
  .info-card { width: 280px; }

  .ent-panel.active { grid-template-columns: 1fr 1fr; }
  .brand-collab h2 { font-size: 32px; }

  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col { border-bottom: 1px solid var(--color-border); }
  .footer-col h5 { padding: 14px 0; margin-bottom: 0; cursor: pointer; display: flex; justify-content: space-between; align-items: center; }
  .footer-col h5::after { content: '+'; font-size: 18px; font-weight: 300; color: var(--color-text-secondary); transition: transform var(--transition); }
  .footer-col.open h5::after { content: '−'; }
  .footer-col ul { max-height: 0; overflow: hidden; transition: max-height 0.4s ease; padding: 0; }
  .footer-col.open ul { max-height: 500px; padding-bottom: 14px; }
}

@media (max-width: 480px) {
  .ent-panel.active { grid-template-columns: 1fr; }
  .hero-tile .hero-ctas { flex-direction: column; gap: 12px; }
  .quick-links-inner { flex-direction: column; align-items: stretch; }
  .quick-link { text-align: center; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }
}

/* ===== FOCUS STYLES ===== */
a:focus-visible, button:focus-visible { outline: 2px solid var(--color-link); outline-offset: 2px; border-radius: 4px; }

/* ===== SAVINGS CARD ===== */
.savings-card { width: 300px; background: #fff; border-radius: var(--card-radius); overflow: hidden; transition: transform var(--transition), box-shadow var(--transition); border: 1px solid #f0f0f0; }
.savings-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.06); }
.savings-card-image { height: 160px; display: flex; align-items: center; justify-content: center; }
.savings-card-image .placeholder-icon { font-size: 40px; opacity: 0.2; }
.savings-card.carrier .savings-card-image { background: linear-gradient(135deg, #eef4ff, #dbeafe); }
.savings-card.edu .savings-card-image { background: linear-gradient(135deg, #f0fdf4, #dcfce7); }
.savings-card.refurb .savings-card-image { background: linear-gradient(135deg, #f5f3ff, #ede9fe); }
.savings-card.business .savings-card-image { background: linear-gradient(135deg, #fefce8, #fef9c3); }
.savings-card.gov .savings-card-image { background: linear-gradient(135deg, #f0f9ff, #e0f2fe); }
.savings-card.military .savings-card-image { background: linear-gradient(135deg, #fdf2f8, #fce7f3); }
.savings-card-info { padding: 20px; }
.savings-card-info h4 { font-size: 16px; font-weight: 600; margin-bottom: 6px; }
.savings-card-info p { font-size: 13px; color: var(--color-text-secondary); line-height: 1.5; }

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg: #fff;
  --color-bg-alt: #f5f5f7;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-link: #0066cc;
  --color-link-hover: #004499;
  --color-border: #d2d2d7;
  --color-card-bg: #fbfbfd;
  --font-stack: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  --max-width: 1440px;
  --section-padding: 80px 0;
  --card-radius: 18px;
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; font-size: 16px; }
body { font-family: var(--font-stack); color: var(--color-text); background: var(--color-bg); line-height: 1.5; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
a { color: var(--color-link); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--color-link-hover); }
img { max-width: 100%; height: auto; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== RIBBON BANNER ===== */
.ribbon { background: var(--color-bg-alt); text-align: center; padding: 12px 24px; font-size: 14px; color: var(--color-text-secondary); }
.ribbon a { font-size: 14px; }

/* ===== TOP NAV ===== */
.top-nav { background: rgba(255,255,255,0.92); backdrop-filter: saturate(180%) blur(20px); -webkit-backdrop-filter: saturate(180%) blur(20px); position: sticky; top: 0; z-index: 1000; border-bottom: 1px solid var(--color-border); }
.top-nav .container { display: flex; align-items: center; justify-content: space-between; height: 48px; }
.nav-logo { font-size: 20px; font-weight: 700; color: var(--color-text); letter-spacing: -0.5px; }
.nav-links { display: flex; gap: 32px; align-items: center; }
.nav-links a { font-size: 13px; color: var(--color-text-secondary); font-weight: 400; transition: color var(--transition); }
.nav-links a:hover { color: var(--color-text); }
.nav-links a.active { color: var(--color-text); font-weight: 600; }
.nav-hamburger { display: none; width: 44px; height: 44px; align-items: center; justify-content: center; flex-direction: column; gap: 5px; }
.nav-hamburger span { display: block; width: 18px; height: 1.5px; background: var(--color-text); transition: var(--transition); }

/* ===== SECTION HEADERS ===== */
.section-header { padding: 0 0 40px; }
.section-header h2 { font-size: 48px; font-weight: 700; letter-spacing: -0.03em; line-height: 1.1; color: var(--color-text); }
.section-header p { font-size: 20px; color: var(--color-text-secondary); margin-top: 8px; font-weight: 400; }

/* ===== CAROUSEL ===== */
.carousel-section { padding: var(--section-padding); overflow: hidden; }
.carousel-wrapper { position: relative; }
.carousel-track { display: flex; gap: 20px; overflow-x: auto; scroll-behavior: smooth; scrollbar-width: none; -ms-overflow-style: none; padding: 4px 0; scroll-snap-type: x mandatory; }
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-track > * { scroll-snap-align: start; flex-shrink: 0; }

.carousel-nav { display: flex; gap: 12px; margin-top: 24px; justify-content: flex-end; padding-right: 4px; }
.carousel-btn { width: 40px; height: 40px; border-radius: 50%; background: var(--color-bg-alt); border: 1px solid var(--color-border); display: flex; align-items: center; justify-content: center; transition: all var(--transition); color: var(--color-text); }
.carousel-btn:hover { background: var(--color-border); }
.carousel-btn:disabled { opacity: 0.3; cursor: default; }
.carousel-btn svg { width: 16px; height: 16px; }

/* ===== PRODUCT CARDS (Latest) ===== */
.product-card { width: 340px; background: var(--color-bg-alt); border-radius: var(--card-radius); overflow: hidden; transition: transform var(--transition), box-shadow var(--transition); }
.product-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.08); }
.product-card-image { height: 260px; display: flex; align-items: center; justify-content: center; position: relative; }
.product-card-image .placeholder-icon { font-size: 64px; color: var(--color-text-secondary); opacity: 0.3; }
.product-card-badge { position: absolute; top: 16px; left: 16px; background: #e8432d; color: #fff; font-size: 11px; font-weight: 600; padding: 4px 10px; border-radius: 12px; letter-spacing: 0.02em; text-transform: uppercase; }
.product-card-info { padding: 24px; }
.product-card-info h3 { font-size: 20px; font-weight: 600; margin-bottom: 4px; }
.product-card-info .tagline { font-size: 14px; color: var(--color-text-secondary); margin-bottom: 16px; line-height: 1.4; }
.product-card-info .price { font-size: 15px; font-weight: 500; }
.product-card-info .monthly { font-size: 13px; color: var(--color-text-secondary); margin-top: 2px; }

/* Color variants for product cards */
.product-card.bg-dark { background: #1d1d1f; color: #f5f5f7; }
.product-card.bg-dark .tagline, .product-card.bg-dark .monthly { color: #a1a1a6; }
.product-card.bg-dark .price { color: #f5f5f7; }
.product-card.bg-blue { background: linear-gradient(135deg, #1a3a5c 0%, #0d2137 100%); color: #f5f5f7; }
.product-card.bg-blue .tagline, .product-card.bg-blue .monthly { color: #a1a1a6; }
.product-card.bg-blue .price { color: #f5f5f7; }
.product-card.bg-warm { background: linear-gradient(135deg, #faf5f0 0%, #f5ede3 100%); }
.product-card.bg-cool { background: linear-gradient(135deg, #eef2f7 0%, #e3eaf5 100%); }
.product-card.bg-green { background: linear-gradient(135deg, #edf5f0 0%, #d8ede0 100%); }
.product-card.bg-purple { background: linear-gradient(135deg, #f0eef5 0%, #e3daf0 100%); }

/* ===== SMALL CARDS (Accessories, Audio, Help, etc.) ===== */
.small-card { width: 280px; background: var(--color-bg-alt); border-radius: var(--card-radius); overflow: hidden; transition: transform var(--transition), box-shadow var(--transition); }
.small-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.08); }
.small-card-image { height: 200px; display: flex; align-items: center; justify-content: center; background: #fff; }
.small-card-image .placeholder-icon { font-size: 48px; color: var(--color-text-secondary); opacity: 0.3; }
.small-card-info { padding: 20px; }
.small-card-info h4 { font-size: 16px; font-weight: 600; margin-bottom: 4px; line-height: 1.3; }
.small-card-info .card-desc { font-size: 13px; color: var(--color-text-secondary); margin-bottom: 8px; line-height: 1.4; }
.small-card-info .card-price { font-size: 15px; font-weight: 600; }
.small-card-info .card-note { font-size: 12px; color: var(--color-link); margin-top: 4px; }

/* ===== HERO PRODUCT GRID (Homepage) ===== */
.hero-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; padding: 60px 0; }
.hero-tile { border-radius: var(--card-radius); overflow: hidden; min-height: 500px; display: flex; flex-direction: column; align-items: center; padding: 48px 32px; text-align: center; position: relative; transition: transform var(--transition); }
.hero-tile:hover { transform: scale(1.01); }
.hero-tile.dark { background: #1d1d1f; color: #f5f5f7; }
.hero-tile.light { background: var(--color-bg-alt); color: var(--color-text); }
.hero-tile.gradient-blue { background: linear-gradient(180deg, #1b3a5c 0%, #0a1f35 100%); color: #f5f5f7; }
.hero-tile.gradient-warm { background: linear-gradient(180deg, #faf5f0 0%, #f0e6d8 100%); color: var(--color-text); }
.hero-tile.gradient-green { background: linear-gradient(180deg, #e8f5e9 0%, #c8e6c9 100%); color: var(--color-text); }
.hero-tile.gradient-purple { background: linear-gradient(180deg, #f3e5f5 0%, #e1bee7 100%); color: var(--color-text); }
.hero-tile h2 { font-size: 40px; font-weight: 700; letter-spacing: -0.03em; margin-bottom: 8px; }
.hero-tile .hero-tagline { font-size: 18px; opacity: 0.85; margin-bottom: 16px; font-weight: 400; }
.hero-tile .hero-ctas { display: flex; gap: 24px; margin-bottom: 32px; }
.hero-tile .hero-ctas a { font-size: 17px; font-weight: 400; }
.hero-tile.dark .hero-ctas a { color: #6bc1ff; }
.hero-tile.light .hero-ctas a, .hero-tile.gradient-warm .hero-ctas a, .hero-tile.gradient-green .hero-ctas a, .hero-tile.gradient-purple .hero-ctas a { color: var(--color-link); }
.hero-tile.gradient-blue .hero-ctas a { color: #6bc1ff; }
.hero-tile .hero-image-area { flex: 1; display: flex; align-items: center; justify-content: center; width: 100%; }
.hero-tile .product-silhouette { width: 280px; height: 200px; border-radius: 20px; display: flex; align-items: center; justify-content: center; }
.hero-tile.dark .product-silhouette { background: rgba(255,255,255,0.06); }
.hero-tile.light .product-silhouette, .hero-tile.gradient-warm .product-silhouette, .hero-tile.gradient-green .product-silhouette, .hero-tile.gradient-purple .product-silhouette { background: rgba(0,0,0,0.04); }
.hero-tile.gradient-blue .product-silhouette { background: rgba(255,255,255,0.06); }
.product-silhouette svg { width: 80px; height: 80px; opacity: 0.25; }

/* ===== ENTERTAINMENT TABS ===== */
.entertainment-section { padding: var(--section-padding); background: var(--color-bg-alt); }
.ent-tabs { display: flex; gap: 8px; margin-bottom: 40px; flex-wrap: wrap; }
.ent-tab { padding: 10px 24px; border-radius: 100px; font-size: 15px; font-weight: 500; color: var(--color-text-secondary); background: #fff; border: 1px solid var(--color-border); transition: all var(--transition); }
.ent-tab:hover { border-color: var(--color-text-secondary); }
.ent-tab.active { background: var(--color-text); color: #fff; border-color: var(--color-text); }
.ent-panel { display: none; }
.ent-panel.active { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 20px; }
.ent-card { background: #fff; border-radius: 16px; overflow: hidden; transition: transform var(--transition), box-shadow var(--transition); }
.ent-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.08); }
.ent-card-image { height: 180px; display: flex; align-items: center; justify-content: center; }
.ent-card-image .placeholder-icon { font-size: 40px; opacity: 0.2; }
.ent-card.streaming .ent-card-image { background: linear-gradient(135deg, #1a1a2e, #16213e); }
.ent-card.fitness .ent-card-image { background: linear-gradient(135deg, #1b4332, #2d6a4f); }
.ent-card.gaming .ent-card-image { background: linear-gradient(135deg, #2d1b69, #4a1a8a); }
.ent-card.music .ent-card-image { background: linear-gradient(135deg, #7f1d1d, #991b1b); }
.ent-card-body { padding: 16px 20px; }
.ent-card-body h4 { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
.ent-card-body p { font-size: 13px; color: var(--color-text-secondary); margin-bottom: 12px; }
.ent-card-body a { font-size: 13px; font-weight: 500; }

/* ===== ICON BAR ===== */
.icon-bar { padding: 32px 0; border-bottom: 1px solid var(--color-border); overflow-x: auto; scrollbar-width: none; -ms-overflow-style: none; }
.icon-bar::-webkit-scrollbar { display: none; }
.icon-bar-inner { display: flex; gap: 40px; justify-content: center; min-width: max-content; padding: 0 24px; }
.icon-item { display: flex; flex-direction: column; align-items: center; gap: 8px; text-decoration: none; color: var(--color-text); transition: opacity var(--transition); min-width: 72px; }
.icon-item:hover { opacity: 0.7; color: var(--color-text); }
.icon-item .icon-circle { width: 56px; height: 56px; border-radius: 50%; background: var(--color-bg-alt); display: flex; align-items: center; justify-content: center; }
.icon-circle svg { width: 24px; height: 24px; color: var(--color-text-secondary); }
.icon-item span { font-size: 12px; color: var(--color-text-secondary); white-space: nowrap; }

/* ===== STORE HERO ===== */
.store-hero { text-align: center; padding: 60px 24px 40px; }
.store-hero h1 { font-size: 56px; font-weight: 700; letter-spacing: -0.04em; }
.store-hero p { font-size: 22px; color: var(--color-text-secondary); margin-top: 8px; }
.store-hero .hero-links { display: flex; gap: 24px; justify-content: center; margin-top: 16px; flex-wrap: wrap; }
.store-hero .hero-links a { font-size: 17px; }

/* ===== HELP & STORE DIFF ===== */
.info-card { width: 300px; background: #fff; border-radius: var(--card-radius); padding: 32px 24px; text-align: center; transition: transform var(--transition), box-shadow var(--transition); border: 1px solid #f0f0f0; }
.info-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.06); }
.info-card .card-icon { width: 48px; height: 48px; margin: 0 auto 16px; border-radius: 50%; background: var(--color-bg-alt); display: flex; align-items: center; justify-content: center; }
.info-card .card-icon svg { width: 22px; height: 22px; color: var(--color-link); }
.info-card h4 { font-size: 17px; font-weight: 600; margin-bottom: 6px; }
.info-card p { font-size: 14px; color: var(--color-text-secondary); line-height: 1.5; }

/* ===== BRAND COLLAB ===== */
.brand-collab { padding: var(--section-padding); text-align: center; background: linear-gradient(135deg, #1d1d1f 0%, #2d2d30 100%); color: #f5f5f7; }
.brand-collab h2 { font-size: 48px; font-weight: 700; letter-spacing: -0.03em; }
.brand-collab p { font-size: 18px; color: #a1a1a6; margin-top: 8px; max-width: 600px; margin-left: auto; margin-right: auto; }

/* ===== QUICK LINKS ===== */
.quick-links { padding: 40px 0; }
.quick-links-inner { display: flex; gap: 12px; flex-wrap: wrap; justify-content: center; }
.quick-link { padding: 10px 24px; border-radius: 100px; border: 1px solid var(--color-border); font-size: 14px; color: var(--color-text); transition: all var(--transition); background: #fff; }
.quick-link:hover { background: var(--color-bg-alt); border-color: var(--color-text-secondary); color: var(--color-text); }

/* ===== CATEGORY PAGE HERO ===== */
.category-hero { text-align: center; padding: 60px 24px 20px; }
.category-hero h1 { font-size: 56px; font-weight: 700; letter-spacing: -0.04em; }
.category-hero p { font-size: 20px; color: var(--color-text-secondary); margin-top: 8px; }

/* ===== STICKY SECTION NAV ===== */
.section-nav { position: sticky; top: 48px; z-index: 900; background: rgba(255,255,255,0.92); backdrop-filter: saturate(180%) blur(20px); -webkit-backdrop-filter: saturate(180%) blur(20px); border-bottom: 1px solid var(--color-border); overflow-x: auto; scrollbar-width: none; -ms-overflow-style: none; }
.section-nav::-webkit-scrollbar { display: none; }
.section-nav-inner { display: flex; gap: 32px; justify-content: center; padding: 0 24px; min-width: max-content; }
.section-nav a { display: block; padding: 14px 0; font-size: 14px; color: var(--color-text-secondary); white-space: nowrap; border-bottom: 2px solid transparent; transition: all var(--transition); }
.section-nav a:hover { color: var(--color-text); }
.section-nav a.active { color: var(--color-text); border-bottom-color: var(--color-text); font-weight: 600; }

/* ===== MODEL CARD ===== */
.model-card { width: 320px; background: var(--color-bg-alt); border-radius: var(--card-radius); overflow: hidden; transition: transform var(--transition), box-shadow var(--transition); }
.model-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.08); }
.model-card-image { height: 240px; display: flex; align-items: center; justify-content: center; position: relative; background: #fff; }
.model-card-image .placeholder-icon { font-size: 56px; opacity: 0.2; }
.model-card-badge { position: absolute; top: 16px; left: 16px; background: #e8432d; color: #fff; font-size: 11px; font-weight: 600; padding: 4px 10px; border-radius: 12px; text-transform: uppercase; }
.model-card-info { padding: 24px; text-align: center; }
.model-card-info h3 { font-size: 22px; font-weight: 600; margin-bottom: 12px; }
.model-card-info .price { font-size: 15px; font-weight: 500; }
.model-card-info .monthly { font-size: 13px; color: var(--color-text-secondary); margin-top: 4px; }
.model-card-info .card-ctas { display: flex; gap: 20px; justify-content: center; margin-top: 16px; }
.model-card-info .card-ctas a { font-size: 14px; }

/* ===== GUIDE/SAVE CARD ===== */
.guide-card { width: 300px; background: var(--color-bg-alt); border-radius: var(--card-radius); padding: 32px 24px; transition: transform var(--transition), box-shadow var(--transition); }
.guide-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.06); }
.guide-card h4 { font-size: 18px; font-weight: 600; margin-bottom: 8px; }
.guide-card p { font-size: 14px; color: var(--color-text-secondary); line-height: 1.5; }
.guide-card a.card-link { display: inline-block; margin-top: 12px; font-size: 14px; font-weight: 500; }

/* ===== FOOTER ===== */
.site-footer { background: var(--color-bg-alt); border-top: 1px solid var(--color-border); padding: 48px 0 24px; margin-top: 60px; }
.footer-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 32px; margin-bottom: 40px; }
.footer-col h5 { font-size: 13px; font-weight: 600; margin-bottom: 12px; color: var(--color-text); cursor: default; }
.footer-col ul li { margin-bottom: 6px; }
.footer-col ul li a { font-size: 12px; color: var(--color-text-secondary); }
.footer-col ul li a:hover { color: var(--color-text); }
.footer-legal { border-top: 1px solid var(--color-border); padding-top: 20px; font-size: 12px; color: var(--color-text-secondary); line-height: 1.6; }
.footer-legal p { margin-bottom: 8px; }
.footer-bottom { display: flex; justify-content: space-between; align-items: center; margin-top: 12px; font-size: 12px; color: var(--color-text-secondary); flex-wrap: wrap; gap: 8px; }

/* ===== PROMO BANNER (in-section) ===== */
.promo-note { font-size: 14px; color: var(--color-link); margin-top: -20px; margin-bottom: 30px; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .hero-grid { grid-template-columns: 1fr 1fr; }
  .hero-tile { min-height: 420px; padding: 36px 24px; }
  .hero-tile h2 { font-size: 32px; }
  .section-header h2 { font-size: 40px; }
  .store-hero h1, .category-hero h1 { font-size: 44px; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-hamburger { display: flex; }
  .nav-links.open { display: flex; position: absolute; top: 48px; left: 0; right: 0; background: rgba(255,255,255,0.98); backdrop-filter: blur(20px); flex-direction: column; gap: 0; padding: 12px 0; border-bottom: 1px solid var(--color-border); }
  .nav-links.open a { padding: 12px 24px; width: 100%; }

  .hero-grid { grid-template-columns: 1fr; }
  .hero-tile { min-height: 380px; }
  .hero-tile h2 { font-size: 28px; }
  .hero-tile .hero-tagline { font-size: 16px; }
  .section-header h2 { font-size: 32px; }
  .store-hero h1, .category-hero h1 { font-size: 36px; }
  .store-hero p, .category-hero p { font-size: 17px; }

  .product-card { width: 300px; }
  .small-card { width: 260px; }
  .model-card { width: 280px; }
  .guide-card { width: 280px; }
  .info-card { width: 280px; }

  .ent-panel.active { grid-template-columns: 1fr 1fr; }
  .brand-collab h2 { font-size: 32px; }

  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col { border-bottom: 1px solid var(--color-border); }
  .footer-col h5 { padding: 14px 0; margin-bottom: 0; cursor: pointer; display: flex; justify-content: space-between; align-items: center; }
  .footer-col h5::after { content: '+'; font-size: 18px; font-weight: 300; color: var(--color-text-secondary); transition: transform var(--transition); }
  .footer-col.open h5::after { content: '−'; }
  .footer-col ul { max-height: 0; overflow: hidden; transition: max-height 0.4s ease; padding: 0; }
  .footer-col.open ul { max-height: 500px; padding-bottom: 14px; }
}

@media (max-width: 480px) {
  .ent-panel.active { grid-template-columns: 1fr; }
  .hero-tile .hero-ctas { flex-direction: column; gap: 12px; }
  .quick-links-inner { flex-direction: column; align-items: stretch; }
  .quick-link { text-align: center; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }
}

/* ===== FOCUS STYLES ===== */
a:focus-visible, button:focus-visible { outline: 2px solid var(--color-link); outline-offset: 2px; border-radius: 4px; }

/* ===== SAVINGS CARD ===== */
.savings-card { width: 300px; background: #fff; border-radius: var(--card-radius); overflow: hidden; transition: transform var(--transition), box-shadow var(--transition); border: 1px solid #f0f0f0; }
.savings-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.06); }
.savings-card-image { height: 160px; display: flex; align-items: center; justify-content: center; }
.savings-card-image .placeholder-icon { font-size: 40px; opacity: 0.2; }
.savings-card.carrier .savings-card-image { background: linear-gradient(135deg, #eef4ff, #dbeafe); }
.savings-card.edu .savings-card-image { background: linear-gradient(135deg, #f0fdf4, #dcfce7); }
.savings-card.refurb .savings-card-image { background: linear-gradient(135deg, #f5f3ff, #ede9fe); }
.savings-card.business .savings-card-image { background: linear-gradient(135deg, #fefce8, #fef9c3); }
.savings-card.gov .savings-card-image { background: linear-gradient(135deg, #f0f9ff, #e0f2fe); }
.savings-card.military .savings-card-image { background: linear-gradient(135deg, #fdf2f8, #fce7f3); }
.savings-card-info { padding: 20px; }
.savings-card-info h4 { font-size: 16px; font-weight: 600; margin-bottom: 6px; }
.savings-card-info p { font-size: 13px; color: var(--color-text-secondary); line-height: 1.5; }

raw_arguments.content:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg: #fff;
  --color-bg-alt: #f5f5f7;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-link: #0066cc;
  --color-link-hover: #004499;
  --color-border: #d2d2d7;
  --color-card-bg: #fbfbfd;
  --font-stack: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  --max-width: 1440px;
  --section-padding: 80px 0;
  --card-radius: 18px;
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; font-size: 16px; }
body { font-family: var(--font-stack); color: var(--color-text); background: var(--color-bg); line-height: 1.5; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
a { color: var(--color-link); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--color-link-hover); }
img { max-width: 100%; height: auto; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== RIBBON BANNER ===== */
.ribbon { background: var(--color-bg-alt); text-align: center; padding: 12px 24px; font-size: 14px; color: var(--color-text-secondary); }
.ribbon a { font-size: 14px; }

/* ===== TOP NAV ===== */
.top-nav { background: rgba(255,255,255,0.92); backdrop-filter: saturate(180%) blur(20px); -webkit-backdrop-filter: saturate(180%) blur(20px); position: sticky; top: 0; z-index: 1000; border-bottom: 1px solid var(--color-border); }
.top-nav .container { display: flex; align-items: center; justify-content: space-between; height: 48px; }
.nav-logo { font-size: 20px; font-weight: 700; color: var(--color-text); letter-spacing: -0.5px; }
.nav-links { display: flex; gap: 32px; align-items: center; }
.nav-links a { font-size: 13px; color: var(--color-text-secondary); font-weight: 400; transition: color var(--transition); }
.nav-links a:hover { color: var(--color-text); }
.nav-links a.active { color: var(--color-text); font-weight: 600; }
.nav-hamburger { display: none; width: 44px; height: 44px; align-items: center; justify-content: center; flex-direction: column; gap: 5px; }
.nav-hamburger span { display: block; width: 18px; height: 1.5px; background: var(--color-text); transition: var(--transition); }

/* ===== SECTION HEADERS ===== */
.section-header { padding: 0 0 40px; }
.section-header h2 { font-size: 48px; font-weight: 700; letter-spacing: -0.03em; line-height: 1.1; color: var(--color-text); }
.section-header p { font-size: 20px; color: var(--color-text-secondary); margin-top: 8px; font-weight: 400; }

/* ===== CAROUSEL ===== */
.carousel-section { padding: var(--section-padding); overflow: hidden; }
.carousel-wrapper { position: relative; }
.carousel-track { display: flex; gap: 20px; overflow-x: auto; scroll-behavior: smooth; scrollbar-width: none; -ms-overflow-style: none; padding: 4px 0; scroll-snap-type: x mandatory; }
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-track > * { scroll-snap-align: start; flex-shrink: 0; }

.carousel-nav { display: flex; gap: 12px; margin-top: 24px; justify-content: flex-end; padding-right: 4px; }
.carousel-btn { width: 40px; height: 40px; border-radius: 50%; background: var(--color-bg-alt); border: 1px solid var(--color-border); display: flex; align-items: center; justify-content: center; transition: all var(--transition); color: var(--color-text); }
.carousel-btn:hover { background: var(--color-border); }
.carousel-btn:disabled { opacity: 0.3; cursor: default; }
.carousel-btn svg { width: 16px; height: 16px; }

/* ===== PRODUCT CARDS (Latest) ===== */
.product-card { width: 340px; background: var(--color-bg-alt); border-radius: var(--card-radius); overflow: hidden; transition: transform var(--transition), box-shadow var(--transition); }
.product-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.08); }
.product-card-image { height: 260px; display: flex; align-items: center; justify-content: center; position: relative; }
.product-card-image .placeholder-icon { font-size: 64px; color: var(--color-text-secondary); opacity: 0.3; }
.product-card-badge { position: absolute; top: 16px; left: 16px; background: #e8432d; color: #fff; font-size: 11px; font-weight: 600; padding: 4px 10px; border-radius: 12px; letter-spacing: 0.02em; text-transform: uppercase; }
.product-card-info { padding: 24px; }
.product-card-info h3 { font-size: 20px; font-weight: 600; margin-bottom: 4px; }
.product-card-info .tagline { font-size: 14px; color: var(--color-text-secondary); margin-bottom: 16px; line-height: 1.4; }
.product-card-info .price { font-size: 15px; font-weight: 500; }
.product-card-info .monthly { font-size: 13px; color: var(--color-text-secondary); margin-top: 2px; }

/* Color variants for product cards */
.product-card.bg-dark { background: #1d1d1f; color: #f5f5f7; }
.product-card.bg-dark .tagline, .product-card.bg-dark .monthly { color: #a1a1a6; }
.product-card.bg-dark .price { color: #f5f5f7; }
.product-card.bg-blue { background: linear-gradient(135deg, #1a3a5c 0%, #0d2137 100%); color: #f5f5f7; }
.product-card.bg-blue .tagline, .product-card.bg-blue .monthly { color: #a1a1a6; }
.product-card.bg-blue .price { color: #f5f5f7; }
.product-card.bg-warm { background: linear-gradient(135deg, #faf5f0 0%, #f5ede3 100%); }
.product-card.bg-cool { background: linear-gradient(135deg, #eef2f7 0%, #e3eaf5 100%); }
.product-card.bg-green { background: linear-gradient(135deg, #edf5f0 0%, #d8ede0 100%); }
.product-card.bg-purple { background: linear-gradient(135deg, #f0eef5 0%, #e3daf0 100%); }

/* ===== SMALL CARDS (Accessories, Audio, Help, etc.) ===== */
.small-card { width: 280px; background: var(--color-bg-alt); border-radius: var(--card-radius); overflow: hidden; transition: transform var(--transition), box-shadow var(--transition); }
.small-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.08); }
.small-card-image { height: 200px; display: flex; align-items: center; justify-content: center; background: #fff; }
.small-card-image .placeholder-icon { font-size: 48px; color: var(--color-text-secondary); opacity: 0.3; }
.small-card-info { padding: 20px; }
.small-card-info h4 { font-size: 16px; font-weight: 600; margin-bottom: 4px; line-height: 1.3; }
.small-card-info .card-desc { font-size: 13px; color: var(--color-text-secondary); margin-bottom: 8px; line-height: 1.4; }
.small-card-info .card-price { font-size: 15px; font-weight: 600; }
.small-card-info .card-note { font-size: 12px; color: var(--color-link); margin-top: 4px; }

/* ===== HERO PRODUCT GRID (Homepage) ===== */
.hero-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; padding: 60px 0; }
.hero-tile { border-radius: var(--card-radius); overflow: hidden; min-height: 500px; display: flex; flex-direction: column; align-items: center; padding: 48px 32px; text-align: center; position: relative; transition: transform var(--transition); }
.hero-tile:hover { transform: scale(1.01); }
.hero-tile.dark { background: #1d1d1f; color: #f5f5f7; }
.hero-tile.light { background: var(--color-bg-alt); color: var(--color-text); }
.hero-tile.gradient-blue { background: linear-gradient(180deg, #1b3a5c 0%, #0a1f35 100%); color: #f5f5f7; }
.hero-tile.gradient-warm { background: linear-gradient(180deg, #faf5f0 0%, #f0e6d8 100%); color: var(--color-text); }
.hero-tile.gradient-green { background: linear-gradient(180deg, #e8f5e9 0%, #c8e6c9 100%); color: var(--color-text); }
.hero-tile.gradient-purple { background: linear-gradient(180deg, #f3e5f5 0%, #e1bee7 100%); color: var(--color-text); }
.hero-tile h2 { font-size: 40px; font-weight: 700; letter-spacing: -0.03em; margin-bottom: 8px; }
.hero-tile .hero-tagline { font-size: 18px; opacity: 0.85; margin-bottom: 16px; font-weight: 400; }
.hero-tile .hero-ctas { display: flex; gap: 24px; margin-bottom: 32px; }
.hero-tile .hero-ctas a { font-size: 17px; font-weight: 400; }
.hero-tile.dark .hero-ctas a { color: #6bc1ff; }
.hero-tile.light .hero-ctas a, .hero-tile.gradient-warm .hero-ctas a, .hero-tile.gradient-green .hero-ctas a, .hero-tile.gradient-purple .hero-ctas a { color: var(--color-link); }
.hero-tile.gradient-blue .hero-ctas a { color: #6bc1ff; }
.hero-tile .hero-image-area { flex: 1; display: flex; align-items: center; justify-content: center; width: 100%; }
.hero-tile .product-silhouette { width: 280px; height: 200px; border-radius: 20px; display: flex; align-items: center; justify-content: center; }
.hero-tile.dark .product-silhouette { background: rgba(255,255,255,0.06); }
.hero-tile.light .product-silhouette, .hero-tile.gradient-warm .product-silhouette, .hero-tile.gradient-green .product-silhouette, .hero-tile.gradient-purple .product-silhouette { background: rgba(0,0,0,0.04); }
.hero-tile.gradient-blue .product-silhouette { background: rgba(255,255,255,0.06); }
.product-silhouette svg { width: 80px; height: 80px; opacity: 0.25; }

/* ===== ENTERTAINMENT TABS ===== */
.entertainment-section { padding: var(--section-padding); background: var(--color-bg-alt); }
.ent-tabs { display: flex; gap: 8px; margin-bottom: 40px; flex-wrap: wrap; }
.ent-tab { padding: 10px 24px; border-radius: 100px; font-size: 15px; font-weight: 500; color: var(--color-text-secondary); background: #fff; border: 1px solid var(--color-border); transition: all var(--transition); }
.ent-tab:hover { border-color: var(--color-text-secondary); }
.ent-tab.active { background: var(--color-text); color: #fff; border-color: var(--color-text); }
.ent-panel { display: none; }
.ent-panel.active { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 20px; }
.ent-card { background: #fff; border-radius: 16px; overflow: hidden; transition: transform var(--transition), box-shadow var(--transition); }
.ent-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,0.08); }
.ent-card-image { height: 180px; display: flex; align-items: center; justify-content: center; }
.ent-card-image .placeholder-icon { font-size: 40px; opacity: 0.2; }
